def transform(grid):
    # The original is an intact gradient grid with some cells erased; recover
    # each erased cell by the regular row progression inferred from its row.
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        candidates=[]
        for c,v in enumerate(row):
            if v:
                candidates.append((v-c-1)%9)
        phase=max(set(candidates), key=candidates.count)
        for c,v in enumerate(row):
            if v==0: out[r][c]=(phase+c)%9+1
    return out
